import java.util.concurrent.*;

public class ThreadPoolMasterclass {
    public static void main(String[] args) {
        // 1. FixedThreadPool: Bounded resource consumption
        ExecutorService fixedPool = Executors.newFixedThreadPool(4);

        // 2. CachedThreadPool: Elastic scaling for short bursts
        ExecutorService cachedPool = Executors.newCachedThreadPool();

        // 3. ScheduledThreadPool: Time-delayed and periodic execution
        ScheduledExecutorService scheduledPool = Executors.newScheduledThreadPool(2);
        scheduledPool.scheduleAtFixedRate(() -> System.out.println("Heartbeat tick"), 0, 1, TimeUnit.SECONDS);

        // 4. SingleThreadExecutor: Guaranteed sequential processing
        ExecutorService singlePool = Executors.newSingleThreadExecutor();

        singlePool.submit(() -> System.out.println("Executing sequentially..."));

        // Graceful shutdown sequence
        fixedPool.shutdown();
        cachedPool.shutdown();
        scheduledPool.shutdown();
        singlePool.shutdown();
    }
}
